/* Terminal navigation. Uses the existing demo routes and application state. */
(() => {
  const groups = [
    ['MARKET WORKSPACE', ['overview', 'chart', 'xray', 'sectors']],
    ['INTELLIGENCE', ['meters', 'engines', 'strategies']],
    ['TRADING DESK', ['signals', 'paper', 'journal']]
  ];
  const names = {meters:'Performance meters',overview:'Command center',chart:'Chart terminal',xray:'Market X-Ray',sectors:'Sector rotation',engines:'Engine Room',strategies:'Strategy library',signals:'Signal center',paper:'Paper execution',journal:'Trade journal',references:'Client references',controls:'Workspace controls',settings:'Preferences'};
  const previous = bindPage;
  const previousAction = action;
  let collapsed = false;
  try { collapsed = localStorage.getItem('frye-nav-collapsed') === 'true'; } catch {}
  function item(id) {
    const def=nav.find(n=>n[0]===id);
    if(!def)return '';
    const active=page===id;
    const count=id==='signals'?allSignals().filter(s=>s.status==='Qualified').length:id==='paper'?state.positions.length:0;
    return `<a class="side-link ${active?'is-current':''}" href="#/${id}" title="${names[id]}" aria-label="${names[id]}" ${active?'aria-current="page"':''}><span class="side-icon">${icon(def[2],17)}</span><span class="side-label">${names[id]}</span>${count?`<span class="side-count ${id==='signals'?'hot':''}">${String(count).padStart(2,'0')}</span>`:''}${active?'<span class="side-current-dot"></span>':''}</a>${id==='engines'&&active?`<div class="side-subnav">${[['structure','22','Wave structure'],['intelligence','27','Trader intelligence'],['planner','26','Location / planner']].map(([view,n,label])=>`<button data-action="engine-tab:${view}" class="${engineView===view?'selected':''}"><span>E${n}</span>${label}<i></i></button>`).join('')}</div>`:''}`;
  }
  function paint() {
    const sidebar=$('.sidebar');
    if(!sidebar)return;
    document.body.classList.toggle('sidebar-collapsed',collapsed);
    sidebar.classList.add('terminal-sidebar');
    const initials=state.settings.name.split(' ').map(x=>x[0]).slice(0,2).join('');
    sidebar.innerHTML=`<div class="terminal-brand-row"><a href="#/overview" class="terminal-brand" aria-label="REDLINE command center"><span class="redline-professional-logo"><img src="data:image/png;base64," alt="REDLINE Trading client speedometer logo" width="62" height="62"><span class="client-brand-copy"><strong>RED<span>LINE</span></strong><small>PERFORMANCE TRADING</small></span></span><span class="redline-compact-logo" aria-hidden="true"><img src="data:image/png;base64," alt="" width="48" height="48"></span></a><button class="side-collapse" data-action="nav-collapse" aria-label="${collapsed?'Expand':'Collapse'} sidebar" title="${collapsed?'Expand':'Collapse'} sidebar"><svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><rect x="3" y="4" width="18" height="16" rx="3"/><path d="M9 4v16 M${collapsed?'13 9l3 3-3 3':'16 9l-3 3 3 3'}"/></svg></button></div><div class="terminal-workspace"><button class="workspace-selector" data-action="nav-workspaces" aria-label="Choose workspace"><span class="workspace-symbol">${icon('grid',17)}</span><span class="workspace-selector-copy"><strong>Personal workspace</strong><small><i></i> Presentation environment</small></span>${icon('down',13)}</button><button class="side-command" data-action="search" aria-label="Search markets"><span>${icon('search',14)}<span>Jump to a market</span></span><kbd>Ctrl K</kbd></button></div><nav class="terminal-nav" aria-label="Trading workspace">${groups.map(([label,ids],i)=>`<section class="side-group"><div class="side-group-label"><span>${label}</span><small>0${i+1}</small></div>${ids.map(item).join('')}</section>`).join('')}<div class="side-utilities">${['references','controls','settings'].map(item).join('')}</div></nav><div class="terminal-bottom"><div class="sidebar-account"><div class="sidebar-account-head"><span>PAPER ACCOUNT</span><span class="account-mono">USD</span></div><div class="sidebar-equity">${money(equity())}<span class="${realized()+unrealized()>=0?'up':'down'}">${signed(realized()+unrealized())}</span></div><div class="sidebar-account-bottom"><span>Practice capital</span><button data-action="paper" title="Open paper execution" aria-label="Open paper execution">${icon('arrow',13)}</button></div></div><div class="terminal-environment"><span><i></i><span>SIMULATED ENVIRONMENT</span></span><button data-action="about" aria-label="About simulation">${icon('info',12)}</button></div><button class="terminal-profile" data-action="settings" aria-label="Profile and preferences"><span class="terminal-avatar">${esc(initials)}</span><span class="terminal-profile-copy"><strong>${esc(state.settings.name)}</strong><small>Personal workspace</small></span><span class="profile-cog">${icon('settings',15)}</span></button></div>`;
    bindActions(sidebar);
    let shade=$('.sidebar-shade');
    if(!shade){shade=document.createElement('button');shade.className='sidebar-shade';shade.setAttribute('aria-label','Close navigation');$('.shell').appendChild(shade)}
    shade.onclick=()=>sidebar.classList.remove('open');
    sidebar.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>sidebar.classList.remove('open')));
  }
  action=function(value){
    if(value==='nav-collapse'){
      if(innerWidth<=650){$('.sidebar').classList.remove('open');return}
      collapsed=!collapsed;
      try{localStorage.setItem('frye-nav-collapsed',String(collapsed))}catch{}
      paint();return;
    }
    if(value==='nav-workspaces'){
      openModal('Choose your workspace',`<p class="metric-description">One demonstration environment, three ways to focus.</p><div class="workspace-options">${[['overview','grid','Command center','Market context, watchlists and the session overview.'],['chart','chart','Chart terminal','Focus on price, structure and a specific setup.'],['engines','shield','Engine Room','Inspect the client’s analytical and permission boundaries.']].map(([id,i,title,desc])=>`<a href="#/${id}" class="workspace-option" data-workspace-target><span class="workspace-option-icon">${icon(i,21)}</span><span><strong>${title}</strong><small>${desc}</small></span>${icon('arrow',16)}</a>`).join('')}</div><div class="notice" style="margin-top:18px;margin-bottom:0">All workspaces share the same simulated account and local demo data.</div>`);
      $$('[data-workspace-target]',$('#modal')).forEach(a=>a.onclick=()=>closeModal());return;
    }
    previousAction(value);
  };
  bindPage=function(){previous();paint()};
  document.addEventListener('keydown',event=>{
    if(event.key==='Escape'&&$('.terminal-sidebar.open')){
      $('.terminal-sidebar').classList.remove('open');
      $('.mobile-menu')?.focus();
    }
  });
  window.fryeNavigation={getCollapsed:()=>collapsed,setCollapsed:(value,persist=false)=>{collapsed=!!value;if(persist){try{localStorage.setItem('frye-nav-collapsed',String(collapsed))}catch{}}paint()}};
  window.addEventListener('frye:reset',()=>{collapsed=false;try{localStorage.removeItem('frye-nav-collapsed')}catch{}paint()});
  paint();
})();


